			return
		}
		req, e := http.NewRequestWithContext(r.Context(), r.Method, target+r.URL.Path, r.Body)
		if e != nil {
			t.Error(e)
			return
		}
		req.Header = r.Header.Clone()
		req.ContentLength = r.ContentLength
		res, e := http.DefaultClient.Do(req)
